class EventSource {
  eventListeners: {[key: string]: Array<(data: unknown) => void>}

  constructor() {
    this.eventListeners = {}
  }

  on(name, callback) {
    let listeners = this.eventListeners[name]
    if (!listeners) listeners = this.eventListeners[name] = []
    listeners.push(callback)
  }

  dispatch(name, data) {
    const listeners = this.eventListeners[name] || []
    for (const c of listeners) {
      requestAnimationFrame(() => c(data))
    }
  }
}

class CanvasView extends EventSource {
  canvas: HTMLCanvasElement
  resizeRequestID?: AnimationFrameID
  repaintRequestID?: AnimationFrameID
  width: number
  height: number

  constructor(canvas: HTMLCanvasElement) {
    super()
    this.canvas = canvas
    this.width = 0
    this.height = 0
  }

  setDimensions(width, height) {
    if (this.resizeRequestID != null) cancelAnimationFrame(this.resizeRequestID)

    this.resizeRequestID = requestAnimationFrame(() => {
      this.setDimensionsNow(width, height)
    })
  }

  setDimensionsNow(width, height) {
    if (width === this.width && height === this.height) return

    this.width = width
    this.height = height

    this.canvas.style.width = `${width}px`
    this.canvas.style.height = `${height}px`

    const ratio = window.devicePixelRatio || 1
    this.canvas.width = width * ratio
    this.canvas.height = height * ratio

    const ctx = this.canvas.getContext('2d')
    ctx.setTransform(1, 0, 0, 1, 0, 0)
    ctx.scale(ratio, ratio)

    this.repaintNow()
  }

  paint() {
    // noop
  }

  scheduleRepaint() {
    if (this.repaintRequestID != null) return

    this.repaintRequestID = requestAnimationFrame(() => {
      this.repaintRequestID = null
      this.repaintNow()
    })
  }

  repaintNow() {
    const ctx = this.canvas.getContext('2d')
    ctx.clearRect(0, 0, this.width, this.height)
    this.paint()

    if (this.repaintRequestID != null) {
      cancelAnimationFrame(this.repaintRequestID)
      this.repaintRequestID = null
    }
  }
}

interface Frame {
  file: string
  frame: string
  frame_id: number
  gemName: string
  topFrame: {
    exclusiveCount: number
  }
  width: number
  x: number
  y: number
}

interface Data {
  frames: string[]
  samples: string[]
  color: [number, number, number]
}

class Flamechart extends CanvasView {
  showLabels: boolean
  data: Frame[]
  dataRange: {
    maxX: number
    maxY: number
    minX: number
    minY: number
  }
  info: Record<string, Data>
  viewport: {
    x: number
    y: number
    width: number
    height: number
  }

  constructor(canvas, data, dataRange, info) {
    super(canvas)

    this.data = data
    this.dataRange = dataRange
    this.info = info

    this.viewport = {
      x: dataRange.minX,
      y: dataRange.minY,
      width: dataRange.maxX - dataRange.minX,
      height: dataRange.maxY - dataRange.minY,
    }
  }

  xScale(x) {
    return this.widthScale(x - this.viewport.x)
  }

  yScale(y) {
    return this.heightScale(y - this.viewport.y)
  }

  widthScale(width) {
    return (width * this.width) / this.viewport.width
  }

  heightScale(height) {
    return (height * this.height) / this.viewport.height
  }

  frameRect(f) {
    return {
      x: f.x,
      y: f.y,
      width: f.width,
      height: 1,
    }
  }

  dataToCanvas(r) {
    return {
      x: this.xScale(r.x),
      y: this.yScale(r.y),
      width: this.widthScale(r.width),
      height: this.heightScale(r.height),
    }
  }

  setViewport(viewport) {
    if (
      this.viewport.x === viewport.x &&
      this.viewport.y === viewport.y &&
      this.viewport.width === viewport.width &&
      this.viewport.height === viewport.height
    )
      return

    this.viewport = viewport

    this.scheduleRepaint()

    this.dispatch('viewportchanged', {current: viewport})
  }

  paint(opacity?: number, frames?: $Iterable<unknown, unknown, unknown>, gemName) {
    const ctx = this.canvas.getContext('2d')

    ctx.strokeStyle = 'rgba(0, 0, 0, 0.2)'

    let characterWidth = 0
    if (this.showLabels) {
      ctx.textBaseline = 'middle'
      ctx.font = `11px ${getComputedStyle(this.canvas).fontFamily}`
      // W tends to be one of the widest characters (and if the font is truly
      // fixed-width then any character will do).
      characterWidth = ctx.measureText('WWWW').width / 4
    }

    if (opacity == null) opacity = 1

    frames = frames || this.data

    const blocksByColor = {}

    for (const f of frames || []) {
      if (gemName && f.gemName !== gemName) continue

      const r = this.dataToCanvas(this.frameRect(f))

      if (r.x >= this.width || r.y >= this.height || r.x + r.width <= 0 || r.y + r.height <= 0) {
        continue
      }

      const i = this.info[f.frame_id]
      const color = colorString(i.color, opacity)
      let colorBlocks = blocksByColor[color]
      if (!colorBlocks) colorBlocks = blocksByColor[color] = []
      colorBlocks.push({rect: r, text: f.frame})
    }

    const textBlocks = []

    for (const color of Object.keys(blocksByColor)) {
      ctx.fillStyle = color

      for (const block of blocksByColor[color]) {
        if (opacity < 1) ctx.clearRect(block.rect.x, block.rect.y, block.rect.width, block.rect.height)

        ctx.fillRect(block.rect.x, block.rect.y, block.rect.width, block.rect.height)

        if (block.rect.width > 4 && block.rect.height > 4)
          ctx.strokeRect(block.rect.x, block.rect.y, block.rect.width, block.rect.height)

        if (!this.showLabels || block.rect.width / characterWidth < 4) continue

        textBlocks.push(block)
      }
    }

    ctx.fillStyle = '#000'
    for (const block of textBlocks) {
      let text = block.text
      const textRect = Object.assign({}, block.rect)
      textRect.x += 1
      textRect.width -= 2
      if (textRect.width < text.length * characterWidth * 0.75)
        text = centerTruncate(block.text, Math.floor(textRect.width / characterWidth))
      ctx.fillText(text, textRect.x, textRect.y + textRect.height / 2, textRect.width)
    }
  }

  frameAtPoint(x, y) {
    return this.data.find(d => {
      const r = this.dataToCanvas(this.frameRect(d))

      return r.x <= x && r.x + r.width >= x && r.y <= y && r.y + r.height >= y
    })
  }
}

class MainFlamechart extends Flamechart {
  dragging: boolean
  dragInfo: {
    mouse: {x: number; y: number}
    viewport: {x: number; y: number}
  }
  hoveredFrame?: Frame

  constructor(canvas, data, dataRange, info) {
    super(canvas, data, dataRange, info)

    this.showLabels = true

    canvas.addEventListener('mousedown', (event: MouseEvent) => this.onMouseDown(event))
    canvas.addEventListener('mousemove', (event: MouseEvent) => this.onMouseMove(event))
    canvas.addEventListener('mouseout', () => this.onMouseOut())
    // eslint-disable-next-line github/require-passive-events
    canvas.addEventListener('wheel', (event: WheelEvent) => this.onWheel(event), {passive: false})
  }

  setDimensionsNow(width, height) {
    const viewport = Object.assign({}, this.viewport)
    viewport.height = height / 16
    this.setViewport(viewport)

    super.setDimensionsNow(width, height)
  }

  onMouseDown(e) {
    if (e.button !== 0) return

    captureMouse({
      mouseup: this.onMouseUp.bind(this),
      mousemove: this.onMouseMove.bind(this),
    })

    const clientRect = this.canvas.getBoundingClientRect()
    const currentX = e.clientX - clientRect.left
    const currentY = e.clientY - clientRect.top

    this.dragging = true
    this.dragInfo = {
      mouse: {x: currentX, y: currentY},
      viewport: {x: this.viewport.x, y: this.viewport.y},
    }

    e.preventDefault()
  }

  onMouseUp(e) {
    if (!this.dragging) return

    releaseCapture()

    this.dragging = false
    e.preventDefault()
  }

  onMouseMove(e) {
    const clientRect = this.canvas.getBoundingClientRect()
    const currentX = e.clientX - clientRect.left
    const currentY = e.clientY - clientRect.top

    if (this.dragging) {
      const viewport = Object.assign({}, this.viewport)
      viewport.x = this.dragInfo.viewport.x - ((currentX - this.dragInfo.mouse.x) * viewport.width) / this.width
      viewport.y = this.dragInfo.viewport.y - ((currentY - this.dragInfo.mouse.y) * viewport.height) / this.height
      viewport.x = Math.min(this.dataRange.maxX - viewport.width, Math.max(this.dataRange.minX, viewport.x))
      viewport.y = Math.min(this.dataRange.maxY - viewport.height, Math.max(this.dataRange.minY, viewport.y))
      this.setViewport(viewport)
      return
    }

    const frame = this.frameAtPoint(currentX, currentY)
    this.setHoveredFrame(frame)
  }

  onMouseOut() {
    if (this.dragging) return

    this.setHoveredFrame(null)
  }

  onWheel(e) {
    const deltaX = e.deltaX
    let deltaY = e.deltaY

    if (e.shiftKey) {
      if (/Macintosh/.test(navigator.userAgent)) {
        // Assume that most Mac users have "Scroll direction: Natural" enabled.
        deltaY *= -1
      }

      const mouseWheelZoomSpeed = 1 / 120
      this.handleZoomGesture(Math.pow(1.2, -(deltaY || deltaX) * mouseWheelZoomSpeed), e.offsetX)
      e.preventDefault()
      return
    }

    const viewport = Object.assign({}, this.viewport)
    viewport.x += (deltaX * viewport.width) / (this.dataRange.maxX - this.dataRange.minX)
    viewport.x = Math.min(this.dataRange.maxX - viewport.width, Math.max(this.dataRange.minX, viewport.x))
    viewport.y += ((deltaY / 8) * viewport.height) / (this.dataRange.maxY - this.dataRange.minY)
    viewport.y = Math.min(this.dataRange.maxY - viewport.height, Math.max(this.dataRange.minY, viewport.y))
    this.setViewport(viewport)
    e.preventDefault()
  }

  handleZoomGesture(zoom, originX) {
    const viewport = Object.assign({}, this.viewport)
    const ratioX = originX / this.width

    const newWidth = Math.min(viewport.width / zoom, this.dataRange.maxX - this.dataRange.minX)
    viewport.x = Math.max(this.dataRange.minX, viewport.x + (viewport.width - newWidth) * ratioX)
    viewport.width = Math.min(newWidth, this.dataRange.maxX - viewport.x)

    this.setViewport(viewport)
  }

  setHoveredFrame(frame) {
    if (frame === this.hoveredFrame) return

    const previous = this.hoveredFrame
    this.hoveredFrame = frame

    this.dispatch('hoveredframechanged', {previous, current: this.hoveredFrame})
  }
}

interface Rect {
  x: number
  y: number
  width: number
  height: number
}

class OverviewFlamechart extends Flamechart {
  container: HTMLElement
  viewportOverlay: HTMLElement
  viewportOverlayRect: Rect
  dragging: unknown
  dragStartX: number
  dragCurrentX: number
  overlayDragging: boolean
  overlayDragInfo: unknown

  constructor(container, viewportOverlay, data, dataRange, info) {
    const canvas = container.querySelector<HTMLCanvasElement>('canvas.overview')!
    super(canvas, data, dataRange, info)

    this.container = container
    this.showLabels = false
    this.viewportOverlay = viewportOverlay

    canvas.addEventListener('mousedown', (event: MouseEvent) => this.onMouseDown(event))

    this.viewportOverlay.addEventListener('mousedown', (event: MouseEvent) => this.onOverlayMouseDown(event))
  }

  setViewportOverlayRect(r) {
    this.viewportOverlayRect = r

    r = this.dataToCanvas(r)
    r.width = Math.max(2, r.width)
    r.height = Math.max(2, r.height)

    if ('transform' in this.viewportOverlay.style) {
      this.viewportOverlay.style.transform = `translate(${r.x}px, ${r.y}px) scale(${r.width}, ${r.height})`
    } else {
      this.viewportOverlay.style.left = `${r.x}px`
      this.viewportOverlay.style.top = `${r.y}px`
      this.viewportOverlay.style.width = `${r.width}px`
      this.viewportOverlay.style.height = `${r.height}px`
    }
  }

  onMouseDown(e) {
    captureMouse({
      mouseup: this.onMouseUp.bind(this),
      mousemove: this.onMouseMove.bind(this),
    })

    this.dragging = true
    this.dragStartX = e.clientX - this.canvas.getBoundingClientRect().left

    this.handleDragGesture(e)

    e.preventDefault()
  }

  onMouseUp(e) {
    if (!this.dragging) return

    releaseCapture()

    this.dragging = false

    this.handleDragGesture(e)

    e.preventDefault()
  }

  onMouseMove(e) {
    if (!this.dragging) return

    this.handleDragGesture(e)

    e.preventDefault()
  }

  handleDragGesture(e) {
    const clientRect = this.canvas.getBoundingClientRect()
    const currentX = e.clientX - clientRect.left
    const currentY = e.clientY - clientRect.top

    if (this.dragCurrentX === currentX) return

    this.dragCurrentX = currentX

    const minX = Math.min(this.dragStartX, this.dragCurrentX)
    const maxX = Math.max(this.dragStartX, this.dragCurrentX)

    const rect = Object.assign({}, this.viewportOverlayRect)
    rect.x = (minX / this.width) * this.viewport.width + this.viewport.x
    rect.width = Math.max(this.viewport.width / 1000, ((maxX - minX) / this.width) * this.viewport.width)

    rect.y = Math.max(
      this.viewport.y,
      Math.min(
        this.viewport.height - this.viewport.y,
        (currentY / this.height) * this.viewport.height + this.viewport.y - rect.height / 2,
      ),
    )

    this.setViewportOverlayRect(rect)
    this.dispatch('overlaychanged', {current: this.viewportOverlayRect})
  }

  onOverlayMouseDown(e) {
    captureMouse({
      mouseup: this.onOverlayMouseUp.bind(this),
      mousemove: this.onOverlayMouseMove.bind(this),
    })

    this.overlayDragging = true
    this.overlayDragInfo = {
      mouse: {x: e.clientX, y: e.clientY},
      rect: Object.assign({}, this.viewportOverlayRect),
    }
    this.viewportOverlay.classList.add('moving')

    this.handleOverlayDragGesture(e)

    e.preventDefault()
  }

  onOverlayMouseUp(e) {
    if (!this.overlayDragging) return

    releaseCapture()

    this.overlayDragging = false
    this.viewportOverlay.classList.remove('moving')

    this.handleOverlayDragGesture(e)

    e.preventDefault()
  }

  onOverlayMouseMove(e) {
    if (!this.overlayDragging) return

    this.handleOverlayDragGesture(e)

    e.preventDefault()
  }

  handleOverlayDragGesture(e) {
    const deltaX = ((e.clientX - this.overlayDragInfo.mouse.x) / this.width) * this.viewport.width
    const deltaY = ((e.clientY - this.overlayDragInfo.mouse.y) / this.height) * this.viewport.height

    const rect = Object.assign({}, this.overlayDragInfo.rect)
    rect.x += deltaX
    rect.y += deltaY
    rect.x = Math.max(this.viewport.x, Math.min(this.viewport.x + this.viewport.width - rect.width, rect.x))
    rect.y = Math.max(this.viewport.y, Math.min(this.viewport.y + this.viewport.height - rect.height, rect.y))

    this.setViewportOverlayRect(rect)
    this.dispatch('overlaychanged', {current: this.viewportOverlayRect})
  }
}

class FlamegraphView {
  data: unknown
  info: unknown
  dataRange: unknown
  mainChart: MainFlamechart
  overview: OverviewFlamechart
  infoElement: HTMLElement
  hoveredGemName: unknown

  constructor(data, info, sortedGems) {
    this.data = data
    this.info = info
    this.dataRange = this.computeDataRange()
    const mainCanvas = document.querySelector<HTMLCanvasElement>('canvas.flamegraph')!
    this.mainChart = new MainFlamechart(mainCanvas, data, this.dataRange, info)
    this.overview = new OverviewFlamechart(
      document.querySelector('.overview-container'),
      document.querySelector('.overview-viewport-overlay'),
      data,
      this.dataRange,
      info,
    )
    this.infoElement = document.querySelector<HTMLElement>('.info')!

    this.mainChart.on('hoveredframechanged', this.onHoveredFrameChanged.bind(this))
    this.mainChart.on('viewportchanged', this.onViewportChanged.bind(this))
    this.overview.on('overlaychanged', this.onOverlayChanged.bind(this))

    const legend = document.querySelector('.legend')!
    this.renderLegend(legend, sortedGems)

    legend.addEventListener('mousemove', (event: MouseEvent) => this.onLegendMouseMove(event))
    legend.addEventListener('mouseout', () => this.onLegendMouseOut())

    /* eslint-disable-next-line github/prefer-observers */
    window.addEventListener('resize', () => this.updateDimensions())

    this.updateDimensions()
  }

  updateDimensions() {
    const margin = {top: 10, right: 10, bottom: 10, left: 10}
    const width = window.innerWidth - 200 - margin.left - margin.right
    const mainChartHeight = Math.ceil(window.innerHeight * 0.8) - margin.top - margin.bottom
    const overviewHeight = Math.floor(window.innerHeight * 0.2) - 60 - margin.top - margin.bottom

    this.mainChart.setDimensions(width + margin.left + margin.right, mainChartHeight + margin.top + margin.bottom)
    this.overview.setDimensions(width + margin.left + margin.right, overviewHeight + margin.top + margin.bottom)
    this.overview.setViewportOverlayRect(this.mainChart.viewport)
  }

  computeDataRange() {
    const range = {minX: Infinity, minY: Infinity, maxX: -Infinity, maxY: -Infinity}
    for (const d of this.data) {
      range.minX = Math.min(range.minX, d.x)
      range.minY = Math.min(range.minY, d.y)
      range.maxX = Math.max(range.maxX, d.x + d.width)
      range.maxY = Math.max(range.maxY, d.y + 1)
    }

    return range
  }

  onHoveredFrameChanged(data) {
    this.updateInfo(data.current)

    if (data.previous) this.repaintFrames(1, this.info[data.previous.frame_id].frames)

    if (data.current) this.repaintFrames(0.5, this.info[data.current.frame_id].frames)
  }

  repaintFrames(opacity, frames) {
    this.mainChart.paint(opacity, frames)
    this.overview.paint(opacity, frames)
  }

  updateInfo(frame) {
    if (!frame) {
      this.infoElement.style.backgroundColor = ''
      this.infoElement.querySelector<HTMLElement>('.frame')!.textContent = ''
      this.infoElement.querySelector<HTMLElement>('.file')!.textContent = ''
      this.infoElement.querySelector<HTMLElement>('.samples')!.textContent = ''
      this.infoElement.querySelector<HTMLElement>('.exclusive')!.textContent = ''
      return
    }

    const i = this.info[frame.frame_id]
    const shortFile = frame.file.replace(/^.+\/(gems|app|lib|config|jobs)/, '$1')
    const sData = this.samplePercentRaw(i.samples.length, frame.topFrame ? frame.topFrame.exclusiveCount : 0)

    this.infoElement.style.backgroundColor = colorString(i.color, 1)
    this.infoElement.querySelector<HTMLElement>('.frame')!.textContent = frame.frame
    this.infoElement.querySelector<HTMLElement>('.file')!.textContent = shortFile
    this.infoElement.querySelector<HTMLElement>('.samples')!.textContent =
      `${sData[0].toString()} samples (${sData[1].toString()}%)`
    if (sData[3]) {
      this.infoElement.querySelector<HTMLElement>('.exclusive')!.textContent =
        `${sData[2].toString()} exclusive (${sData[3].toString()}%)`
    } else {
      this.infoElement.querySelector<HTMLElement>('.exclusive')!.textContent = ''
    }
  }

  samplePercentRaw(samples, exclusive) {
    let ret = [samples, ((samples / this.dataRange.maxX) * 100).toFixed(2)]
    if (exclusive != null) ret = ret.concat([exclusive, ((exclusive / this.dataRange.maxX) * 100).toFixed(2)])
    return ret
  }

  onViewportChanged(data) {
    this.overview.setViewportOverlayRect(data.current)
  }

  onOverlayChanged(data) {
    this.mainChart.setViewport(data.current)
  }

  renderLegend(element, sortedGems) {
    const fragment = document.createDocumentFragment()

    for (const gem of sortedGems) {
      const sData = this.samplePercentRaw(gem.samples.length)
      const node = document.createElement('div')
      node.className = 'legend-gem'
      node.setAttribute('data-gem-name', gem.name)
      node.style.backgroundColor = colorString(gem.color, 1)

      const span = document.createElement('span')
      span.style.float = 'right'
      span.textContent = `${sData[0].toString()}x`
      span.appendChild(document.createElement('br'))
      span.appendChild(document.createTextNode(`${sData[1].toString()}%`))
      node.appendChild(span)

      const name = document.createElement('div')
      name.className = 'name'
      name.textContent = gem.name
      name.appendChild(document.createElement('br'))
      name.appendChild(document.createTextNode('\u00a0'))
      node.appendChild(name)

      fragment.appendChild(node)
    }

    element.appendChild(fragment)
  }

  onLegendMouseMove(event) {
    const gemElement = event.target.closest('.legend-gem')
    const gemName = gemElement.getAttribute('data-gem-name')

    if (this.hoveredGemName === gemName) return

    if (this.hoveredGemName) {
      this.mainChart.paint(1, null, this.hoveredGemName)
      this.overview.paint(1, null, this.hoveredGemName)
    }

    this.hoveredGemName = gemName

    this.mainChart.paint(0.5, null, this.hoveredGemName)
    this.overview.paint(0.5, null, this.hoveredGemName)
  }

  onLegendMouseOut() {
    if (!this.hoveredGemName) return

    this.mainChart.paint(1, null, this.hoveredGemName)
    this.overview.paint(1, null, this.hoveredGemName)
    this.hoveredGemName = null
  }
}

let capturingListeners = null
function captureMouse(listeners) {
  if (capturingListeners) releaseCapture()

  for (const name in listeners) document.addEventListener(name, listeners[name], true)
  capturingListeners = listeners
}

function releaseCapture() {
  if (!capturingListeners) return

  for (const name in capturingListeners) document.removeEventListener(name, capturingListeners[name], true)
  capturingListeners = null
}

function guessGem(frame) {
  let split = frame.split('/gems/')
  if (split.length === 1) {
    split = frame.split('/app/')
    if (split.length === 1) {
      split = frame.split('/lib/')
    } else {
      return split[split.length - 1].split('/')[0]
    }

    split = split[Math.max(split.length - 2, 0)].split('/')
    return split[split.length - 1].split(':')[0]
  } else {
    return split[split.length - 1].split('/')[0].split('-', 2)[0]
  }
}

function color() {
  const r = parseInt(205 + Math.random() * 50)
  const g = parseInt(Math.random() * 230)
  const b = parseInt(Math.random() * 55)
  return [r, g, b]
}

// http://stackoverflow.com/a/7419630
function rainbow(numOfSteps, step) {
  // This function generates vibrant, "evenly spaced" colours (i.e. no clustering). This is ideal for creating easily distiguishable vibrant markers in Google Maps and other apps.
  // Adam Cole, 2011-Sept-14
  // HSV to RBG adapted from: http://mjijackson.com/2008/02/rgb-to-hsl-and-rgb-to-hsv-color-model-conversion-algorithms-in-javascript

  // Unfortunately flow's definite assignment doesn't handle the switch statement properly.
  let r = 0
  let g = 0
  let b = 0
  const h = step / numOfSteps
  const i = ~~(h * 6)
  const f = h * 6 - i
  const q = 1 - f
  switch (i % 6) {
    case 0:
      r = 1
      g = f
      b = 0
      break
    case 1:
      r = q
      g = 1
      b = 0
      break
    case 2:
      r = 0
      g = 1
      b = f
      break
    case 3:
      r = 0
      g = q
      b = 1
      break
    case 4:
      r = f
      g = 0
      b = 1
      break
    case 5:
      r = 1
      g = 0
      b = q
      break
  }
  return [Math.floor(r * 255), Math.floor(g * 255), Math.floor(b * 255)]
}

function colorString(color, opacity) {
  if (opacity == null) opacity = 1
  return `rgba(${color.join(',')},${opacity})`
}

// http://stackoverflow.com/questions/1960473/unique-values-in-an-array
function getUnique(orig) {
  const o = {}
  for (let i = 0; i < orig.length; i++) o[orig[i]] = 1
  return Object.keys(o)
}

function centerTruncate(text, maxLength) {
  const charactersToKeep = maxLength - 1
  if (charactersToKeep <= 0) return ''
  if (text.length <= charactersToKeep) return text

  const prefixLength = Math.ceil(charactersToKeep / 2)
  const suffixLength = charactersToKeep - prefixLength
  const prefix = text.substr(0, prefixLength)
  const suffix = suffixLength > 0 ? text.substr(-suffixLength) : ''

  return [prefix, '\u2026', suffix].join('')
}

export default function flamegraph(data: unknown): void {
  const info = {}
  for (const d of data) {
    let i = info[d.frame_id]
    if (!i) info[d.frame_id] = i = {frames: [], samples: [], color: color()}
    i.frames.push(d)
    for (let j = 0; j < d.width; j++) {
      i.samples.push(d.x + j)
    }
  }

  // Samples may overlap on the same line
  for (const r in info) {
    if (info[r].samples) {
      info[r].samples = getUnique(info[r].samples)
    }
  }

  // assign some colors, analyze samples per gem
  const gemStats = {}
  const topFrames = {}
  let lastFrame = {frame: 'd52e04d-df28-41ed-a215-b6ec840a8ea5', x: -1, frame_id: -1, topFrame: {}}

  for (const d of data) {
    const gem = guessGem(d.file)
    let stat = gemStats[gem]
    d.gemName = gem

    if (!stat) {
      gemStats[gem] = stat = {name: gem, samples: [], frames: []}
    }

    stat.frames.push(d.frame_id)
    for (let j = 0; j < d.width; j++) {
      stat.samples.push(d.x + j)
    }
    // This assumes the traversal is in order
    if (lastFrame.x !== d.x) {
      let topFrame = topFrames[lastFrame.frame_id]
      if (!topFrame) {
        topFrames[lastFrame.frame_id] = topFrame = {exclusiveCount: 0}
      }
      topFrame.exclusiveCount += 1
      lastFrame.topFrame = topFrame
    }
    lastFrame = d
  }

  let topFrame = topFrames[lastFrame.frame_id]
  if (!topFrame) {
    topFrames[lastFrame.frame_id] = topFrame = {exclusiveCount: 0}
  }
  topFrame.exclusiveCount += 1
  lastFrame.topFrame = topFrame

  let totalGems = 0
  for (const k in gemStats) {
    totalGems++
    gemStats[k].samples = getUnique(gemStats[k].samples)
  }

  const gemsSorted = Object.keys(gemStats).map(k => gemStats[k])
  gemsSorted.sort((a, b) => b.samples.length - a.samples.length)

  let currentIndex = 0
  for (const stat of gemsSorted) {
    stat.color = rainbow(totalGems, currentIndex)
    currentIndex += 1

    for (let x = 0; x < stat.frames.length; x++) {
      info[stat.frames[x]].color = stat.color
    }
  }

  document.querySelector<HTMLElement>('.spinner-container')!.remove()
  new FlamegraphView(data, info, gemsSorted)
}
